import java.util.*;
import java.io.*;

public class Main {
    static final int Lg = 18;
    static final int Tw = 1 << Lg;
    static final int Max = Tw + 10;
    static int[][] arr = new int[Max][Lg + 3];
    static int[] temp = new int[Lg + 3];
    static int[] temp2 = new int[Lg + 3];
    static long[] fact = new long[Max];
    static long[] inv_fact = new long[Max];
    static int Nbits;
    static int nVal;
    static int mod = 1000000007;
    static List<Integer> positions = new ArrayList<>();

    static int mod_pow(int base, int exp) {
        long res = 1;
        long b = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return (int) res;
    }

    static void add_to(int[] a, int[] b) {
        for (int i = 0; i <= Nbits; i++) {
            a[i] = (a[i] + b[i]) % mod;
        }
    }

    static void subtract_from(int[] a, int[] b) {
        for (int i = 0; i <= Nbits; i++) {
            a[i] = (a[i] - b[i]) % mod;
            if (a[i] < 0) a[i] += mod;
        }
    }

    static void convolve_arrays(int[] res, int[] a, int[] b) {
        Arrays.fill(temp, 0);
        for (int i = 0; i <= Nbits; i++) {
            for (int j = 0; j <= i; j++) {
                temp[i] = (int) ((temp[i] + 1L * a[j] * b[i - j]) % mod);
            }
        }
        System.arraycopy(temp, 0, res, 0, Nbits + 1);
    }

    static void forward_transform(int[][] a) {
        for (int i = 0; i < Nbits; i++) {
            for (int msk = nVal; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    add_to(a[msk], a[msk ^ (1 << i)]);
                }
            }
        }
    }

    static void inverse_transform(int[][] a) {
        for (int i = 0; i < Nbits; i++) {
            for (int msk = nVal; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    subtract_from(a[msk], a[msk ^ (1 << i)]);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int nValInput = sc.nextInt();
        int K = sc.nextInt();
        int modInput = sc.nextInt();
        mod = modInput;

        int total = mod_pow(K, nValInput);
        if ((nValInput & 1) == 1) {
            System.out.println(total);
            return;
        }

        Nbits = Integer.bitCount(nValInput);
        int original_n = nValInput;

        for (int i = 0; i < Lg; i++) {
            if (((nValInput >> i) & 1) == 1) {
                positions.add(i);
            }
        }

        nVal = (1 << Nbits) - 1;

        fact[0] = 1;
        for (int i = 1; i < Max; i++) {
            fact[i] = (fact[i - 1] * i) % mod;
        }

        inv_fact[Max - 1] = mod_pow((int) fact[Max - 1], mod - 2);
        for (int i = Max - 2; i >= 0; i--) {
            inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % mod;
        }

        for (int i = 0; i <= nVal; i++) {
            int val = 0;
            for (int j = 0; j < Nbits; j++) {
                if (((i >> j) & 1) == 1) {
                    val += (1 << positions.get(j));
                }
            }
            arr[i][Integer.bitCount(i)] = (int) inv_fact[val];
        }

        forward_transform(arr);

        for (int i = 0; i <= nVal; i++) {
            int K_copy = K;
            Arrays.fill(temp2, 0);
            temp2[0] = 1;
            while (K_copy > 0) {
                if ((K_copy & 1) == 1) {
                    convolve_arrays(temp2, temp2, arr[i]);
                }
                convolve_arrays(arr[i], arr[i], arr[i]);
                K_copy >>= 1;
            }
            System.arraycopy(temp2, 0, arr[i], 0, Nbits + 1);
        }

        inverse_transform(arr);

        long answer = (total - 1L * arr[nVal][Nbits] * fact[original_n]) % mod;
        if (answer < 0) answer += mod;
        System.out.println(answer);
    }
}
